type UpsertSectionParams struct {
	DocumentID   int64
	ParentID     *int64
	NodeKey      *string
	Ptype        pgtype.Int2
	Kind         string
	Ordinal      int32
	Label        *string
	Heading      *string
	CitationPath string
	Content      *string
}

// Idempotent on (document_id, citation_path) so re-parsing the provision tree
// converges. parent_id is resolved by the caller before insert.
func (q *Queries) UpsertSection(ctx context.Context, arg UpsertSectionParams) (int64, error) {
	row := q.db.QueryRow(ctx, upsertSection,
		arg.DocumentID,
		arg.ParentID,
		arg.NodeKey,
		arg.Ptype,
		arg.Kind,
		arg.Ordinal,
		arg.Label,
		arg.Heading,
		arg.CitationPath,
		arg.Content,
	)
	var id int64
	err := row.Scan(&id)
	return id, err
}
